class MyArray extends Array {
  static get [Symbol.species]() {
    return Array
  }
}
const myArr = new MyArray(1, 2, 3)
const mapped = myArr.map(x => x * 2)
return {
  isMyArray: myArr instanceof MyArray,
  isArray: mapped instanceof Array,
  isMyArrayType: mapped instanceof MyArray
}
